using System;

public class Program
{
    public static bool isMinorNumber(int num)
    {
        int a = num / 100;
        int b = num / 10 % 10;
        int c = num % 10;
        return Math.Abs(a - b) <= 3 && Math.Abs(a - c) <= 3 && Math.Abs(b - c) <= 3;
    }

    public static void Main()
    {
        Random rnd = new Random();
        int found = 0;
        while (found < 10)
        {
            int num = rnd.Next(100, 1000);
            if (isMinorNumber(num))
            {
                Console.WriteLine(num);
                found++;
            }
        }
    }
}
